const request = $input.first().json || {};
const headers = request.headers || {};
const body = request.body && typeof request.body === 'object' ? request.body : {};
const executionMode = String(body.execution_mode || 'manual').trim().toLowerCase();
const runAiRequested = body.run_ai === true || String(body.run_ai || '').toLowerCase() === 'true';
const executarIaMensal = executionMode === 'monthly_automatic' && runAiRequested;

const expected = String(request.n8n_leme_secret || '');
const received = String(headers['x-leme-n8n-key'] || headers['X-LEME-N8N-KEY'] || '');

const safeEqual = (a, b) => {
  if (!a || !b || a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
};

const required = ['client_name', 'file_name', 'caption', 'pdf_base64', 'scan_summary', 'profile_place_id'];
const missing = required.filter((key) => body[key] === undefined || body[key] === null || body[key] === '');
const configured = expected && !expected.startsWith('COLE_AQUI_');
const authorized = configured && safeEqual(received, expected) && missing.length === 0;

const auditData = {
  cliente: {
    nome: body.client_name || '',
    especialidade: body.specialty || '',
    cidade: body.city || '',
    endereco: body.address || '',
    palavra_chave: body.keyword || ''
  },
  perfil_google: {
    place_id: body.profile_place_id || '',
    google_maps_url: body.profile_google_maps_url || '',
    dados_places: body.profile_snapshot || {}
  },
  local_radar: {
    competencia: body.month_label || '',
    grid: body.grid_size || null,
    raio_km: body.radius_km || null,
    resumo: body.scan_summary || {},
    pontos: Array.isArray(body.grid_points) ? body.grid_points : [],
    concorrentes: Array.isArray(body.competitors) ? body.competitors : []
  },
  benchmark_concorrentes: Array.isArray(body.competitor_snapshots) ? body.competitor_snapshots : []
};

const profilePhotos = Array.isArray(body.profile_photos) ? body.profile_photos.slice(0, 6) : [];
const binary = {};
profilePhotos.forEach((photo, index) => {
  const data = String(photo?.data || '').replace(/^data:image\/[^;]+;base64,/, '');
  if (!data) return;
  binary['profile_photo_' + String(index + 1)] = {
    data,
    mimeType: String(photo?.mime_type || 'image/jpeg'),
    fileName: String(photo?.file_name || ('perfil-google-' + String(index + 1) + '.jpg'))
  };
});
auditData.perfil_google.amostras_visuais_incluidas = Object.keys(binary).length;

const auditPrompt = [
  'Produza uma auditoria PROFUNDA do Google Business Profile e uma estratégia consistente para aumentar a participação em Top 1 e Top 3 no Local Pack.',
  '',
  'IDENTIFICAÇÃO OBRIGATÓRIA:',
  '- Confirme o perfil exato por nome, endereço, cidade, Place ID e URL do Google Maps.',
  '- Não misture homônimos. Quando uma fonte não for o perfil exato, descarte-a.',
  '',
  'DADOS E BENCHMARK JÁ COLETADOS PELO SISTEMA:',
  JSON.stringify(auditData, null, 2),
  '',
  'Há ' + String(Object.keys(binary).length) + ' foto(s) reais do perfil anexada(s). Analise individualmente e também como conjunto: qualidade, variedade, autenticidade, enquadramento, legibilidade, confiança, reconhecimento da entrada e utilidade para o paciente. São amostras, não necessariamente a galeria inteira.',
  '',
  'PESQUISA WEB OBRIGATÓRIA:',
  '- Faça de 6 a 12 pesquisas direcionadas, usando variações de nome, especialidade, cidade, endereço e concorrentes líderes.',
  '- Consulte perfil/links do Google, site oficial, páginas de serviços, Doctoralia, Instagram e outras fontes públicas pertinentes.',
  '- Para cada concorrente do benchmark, identifique sinais públicos úteis: site, páginas locais, serviços, autoridade, conteúdo, avaliações, fotos e clareza de conversão.',
  '- Se o Maps não abrir, use os dados oficiais do Places já fornecidos, URLs diretas, snippets da busca e fontes públicas cruzadas. Não transforme limitações técnicas no foco do relatório.',
  '',
  'A estratégia deve perseguir o objetivo de primeira posição, mas deixar claro que posição orgânica não é garantida e varia por localização. Trabalhe com metas mensuráveis de Top 1, Top 3, média e conversão.',
  'Entregue a auditoria final completa, pronta para ser enviada ao time da LEME no WhatsApp.'
].join('\n');

return [{
  json: {
    ...body,
    execution_mode: executionMode,
    run_ai: executarIaMensal,
    _executar_ia_mensal: executarIaMensal,
    grupo_leme: String(request.grupo_leme || ''),
    evolution_instance: String(request.evolution_instance || 'Leme Marketing Médico'),
    _authorized: authorized,
    _auth_error: !configured
      ? 'Configure n8n_leme_secret no nó CONFIGURAÇÃO — EDITE AQUI.'
      : (!safeEqual(received, expected)
          ? 'X-LEME-N8N-KEY inválida.'
          : (missing.length ? 'Payload incompleto: ' + missing.join(', ') : '')),
    audit_data: auditData,
    audit_prompt: auditPrompt
  },
  binary
}];

const item = $input.first().json || {};
const source = String(item.output || '').trim() || 'A auditoria de IA não retornou conteúdo.';
const prepared = $('Validar e preparar auditoria').first().json || {};
const audit = prepared.audit_data || {};
const client = audit.cliente || {};
const radar = audit.local_radar || {};
const summary = radar.resumo || {};
const profile = audit.perfil_google?.dados_places || {};
const competitors = Array.isArray(radar.concorrentes) ? radar.concorrentes : [];
const benchmark = Array.isArray(audit.benchmark_concorrentes) ? audit.benchmark_concorrentes : [];

const escapeHtml = (value) => String(value ?? '').replace(/[&<>"']/g, (char) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
}[char]));
const number = (value, digits = 0) => value === null || value === undefined || value === ''
  ? '—'
  : new Intl.NumberFormat('pt-BR', { minimumFractionDigits: digits, maximumFractionDigits: digits }).format(Number(value));
const percent = (value) => value === null || value === undefined || value === '' ? '—' : number(value, 1) + '%';
const slug = (value) => String(value || 'cliente').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

const inline = (value) => {
  let safe = escapeHtml(value);
  safe = safe.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>').replace(/\*(.+?)\*/g, '<strong>$1</strong>');
  safe = safe.replace(/\[(Verificado|Inferência|A validar no painel)\]/gi, (_, label) => '<span class="badge">' + label + '</span>');
  safe = safe.replace(/(https?:\/\/[^\s<]+)/g, '<a href="$1">$1</a>');
  return safe;
};

const renderContent = (text) => {
  const lines = String(text).replace(/\r/g, '').split('\n');
  const blocks = [];
  let list = '';
  const closeList = () => { if (list) { blocks.push('</' + list + '>'); list = ''; } };
  for (const raw of lines) {
    const line = raw.trim();
    if (!line) { closeList(); continue; }
    if (/AUDITORIA GBP PROFUNDA/i.test(line)) continue;
    if (/^[📌📍🌐🥇🎯🗓️📸⭐📈✅⚠️🔗]/u.test(line)) {
      closeList();
      const title = line.replace(/^.{1,3}\s*/u, '').replace(/^\*+|\*+$/g, '');
      blocks.push('<h2>' + inline(title) + '</h2>');
      continue;
    }
    const bullet = line.match(/^[•*-]\s+(.+)/);
    if (bullet) {
      if (list !== 'ul') { closeList(); blocks.push('<ul>'); list = 'ul'; }
      blocks.push('<li>' + inline(bullet[1]) + '</li>');
      continue;
    }
    const ordered = line.match(/^\d+[.)]\s+(.+)/);
    if (ordered) {
      if (list !== 'ol') { closeList(); blocks.push('<ol>'); list = 'ol'; }
      blocks.push('<li>' + inline(ordered[1]) + '</li>');
      continue;
    }
    closeList();
    blocks.push('<p>' + inline(line) + '</p>');
  }
  closeList();
  return blocks.join('');
};

const points = Array.isArray(radar.pontos) ? radar.pontos : [];
const top1 = points.length ? points.filter((point) => Number(point.position) === 1).length / points.length * 100 : null;
const targetGrid = competitors.find((entry) => entry?.isTarget) || {};
const rows = benchmark.slice(0, 5).map((entry) => {
  const rank = entry.ranking_grid || {};
  const data = entry.perfil_google || {};
  return '<tr><td><strong>' + escapeHtml(rank.nome || data.name || 'Concorrente') + '</strong></td><td>' + number(rank.posicao_media, 2) + '</td><td>' + number(data.rating, 1) + '</td><td>' + number(data.review_count) + '</td><td>' + escapeHtml(data.primary_category || data.google_maps_category || '—') + '</td><td>' + number(data.photo_count) + '</td></tr>';
}).join('');
const benchmarkRows = '<tr class="target"><td><strong>' + escapeHtml(client.nome || profile.name || 'Cliente') + '</strong><small>Cliente analisado</small></td><td>' + number(targetGrid.averagePosition ?? summary.averagePosition, 2) + '</td><td>' + number(profile.rating, 1) + '</td><td>' + number(profile.review_count) + '</td><td>' + escapeHtml(profile.primary_category || profile.google_maps_category || '—') + '</td><td>' + number(profile.photo_count) + '</td></tr>' + rows;

const photos = Array.isArray(prepared.profile_photos) ? prepared.profile_photos.slice(0, 6) : [];
const photoHtml = photos.length ? '<section class="card photo-section"><h2>Amostras visuais do perfil</h2><p class="section-lead">Imagens públicas analisadas pela IA. A seleção é uma amostra e não representa necessariamente toda a galeria.</p><div class="photo-grid">' + photos.map((photo, index) => {
  const mime = String(photo?.mime_type || 'image/jpeg');
  const data = String(photo?.data || '').replace(/^data:image\/[^;]+;base64,/, '');
  return data ? '<figure><img src="data:' + escapeHtml(mime) + ';base64,' + data + '"><figcaption>Amostra ' + String(index + 1) + '</figcaption></figure>' : '';
}).join('') + '</div></section>' : '';

const competence = radar.competencia || '';
const generatedAt = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const reportBody = renderContent(source);
const lemeLogo = 'data:image/png;base64,';

const html = `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><style>
@page{size:A4 portrait;margin:12mm 14mm 12mm}*{box-sizing:border-box}html{font-size:12px}body{margin:0;font-family:Arial,Helvetica,sans-serif;color:#17324a;background:#fff;line-height:1.55}.cover{min-height:258mm;display:flex;flex-direction:column;justify-content:space-between;padding:18mm 14mm;border-radius:18px;background:linear-gradient(145deg,#0b2235 0%,#123f61 58%,#2f8fc0 100%);color:#fff;page-break-after:always}.cover-logo{width:220px;height:auto}.eyebrow{margin:0 0 10px;text-transform:uppercase;letter-spacing:1.8px;font-size:10px;font-weight:700;color:#a8d8ef}.cover h1{margin:0;max-width:560px;font-size:34px;line-height:1.05}.cover h2{margin:14px 0 0;font-size:22px;color:#d5effb}.cover-meta{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:28px}.cover-meta div{padding:14px;border:1px solid rgba(255,255,255,.2);border-radius:12px;background:rgba(255,255,255,.08)}.cover-meta small{display:block;color:#b9d8e7;margin-bottom:4px}.cover-meta strong{font-size:14px}.cover-footer{display:flex;justify-content:space-between;border-top:1px solid rgba(255,255,255,.2);padding-top:13px;font-size:10px;color:#c8dfeb}.section-title{margin:0 0 14px;font-size:22px;color:#0b2235}.kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-bottom:16px}.kpi{padding:14px;border:1px solid #d9e5ec;border-radius:12px;background:#f5f9fb}.kpi small{display:block;color:#6d8291;font-weight:700;margin-bottom:5px}.kpi strong{font-size:22px;color:#123f61}.card{margin:0 0 15px;padding:17px;border:1px solid #d9e5ec;border-radius:14px;background:#fff;break-inside:avoid}.card h2,.content h2{margin:0 0 10px;padding-bottom:7px;border-bottom:2px solid #dceaf1;color:#123f61;font-size:18px;break-after:avoid}.section-lead{color:#6b7f8d;margin-top:-3px}.table-wrap{overflow:hidden}.benchmark{width:100%;border-collapse:collapse;font-size:10px}.benchmark th{padding:8px 6px;text-align:left;background:#0f334e;color:#fff}.benchmark td{padding:8px 6px;border-bottom:1px solid #e4ebef;vertical-align:top}.benchmark tr.target{background:#eaf6fb}.benchmark small{display:block;color:#2f8fc0;margin-top:2px}.photo-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.photo-grid figure{margin:0;border:1px solid #dce6eb;border-radius:10px;overflow:hidden;background:#f6f9fa}.photo-grid img{display:block;width:100%;height:112px;object-fit:cover}.photo-grid figcaption{padding:5px 7px;color:#6f818d;font-size:9px}.content{font-size:11px}.content h2{margin-top:18px;padding:10px 12px;border:0;border-left:5px solid #2f8fc0;border-radius:8px;background:#edf6fa}.content p{margin:7px 0}.content ul,.content ol{margin:7px 0 12px;padding-left:22px}.content li{margin:5px 0;break-inside:avoid}.content a{color:#246f9a;text-decoration:none;word-break:break-all}.badge{display:inline-block;padding:1px 6px;border-radius:8px;background:#e4f1f7;color:#1d6389;font-size:9px;font-weight:700}.report-footer{margin-top:18px;padding-top:10px;border-top:1px solid #d9e5ec;color:#718490;font-size:9px;text-align:center}.intro-page{}.note{padding:11px 13px;border-radius:10px;background:#fff8e6;color:#6f5517;font-size:10px}strong{color:inherit}
</style></head><body>
<section class="cover"><div><img class="cover-logo" src="${lemeLogo}"><div style="margin-top:46mm"><p class="eyebrow">Relatório estratégico de presença local</p><h1>Auditoria Google Business Profile</h1><h2>${escapeHtml(client.nome || 'Cliente')}</h2><div class="cover-meta"><div><small>Palavra-chave analisada</small><strong>${escapeHtml(client.palavra_chave || '—')}</strong></div><div><small>Competência</small><strong>${escapeHtml(competence || 'Análise atual')}</strong></div><div><small>Cidade</small><strong>${escapeHtml(client.cidade || '—')}</strong></div><div><small>Place ID</small><strong>${escapeHtml(audit.perfil_google?.place_id || '—')}</strong></div></div></div></div><footer class="cover-footer"><span>LEME Marketing Médico</span><span>Gerado em ${escapeHtml(generatedAt)}</span></footer></section>
<section class="intro-page"><h1 class="section-title">Panorama atual</h1><div class="kpis"><div class="kpi"><small>Posição média</small><strong>${number(summary.averagePosition,2)}</strong></div><div class="kpi"><small>Top 1</small><strong>${percent(top1)}</strong></div><div class="kpi"><small>Top 3</small><strong>${percent(summary.top3Percent)}</strong></div><div class="kpi"><small>Top 10</small><strong>${percent(summary.top10Percent)}</strong></div><div class="kpi"><small>Melhor posição</small><strong>${number(summary.bestPosition)}</strong></div><div class="kpi"><small>Pior posição</small><strong>${number(summary.worstPosition)}</strong></div></div><section class="card table-wrap"><h2>Benchmark dos perfis líderes</h2><table class="benchmark"><thead><tr><th>Perfil</th><th>Média</th><th>Nota</th><th>Avaliações</th><th>Categoria</th><th>Fotos*</th></tr></thead><tbody>${benchmarkRows}</tbody></table><p class="note">* O Google Places disponibiliza uma amostra limitada de fotos; o número exibido não deve ser tratado como total absoluto da galeria.</p></section>${photoHtml}</section>
<main class="content">${reportBody}<footer class="report-footer">LEME Marketing Médico · Auditoria GBP gerada automaticamente com dados do Local Radar, Google Places e fontes públicas.</footer></main>
</body></html>`;

const nomeArquivoPdf = 'auditoria-gbp-' + slug(client.nome) + '-' + slug(competence || new Date().toISOString().slice(0, 7)) + '.pdf';
const caption = '🔎 *Auditoria GBP completa — ' + String(client.nome || 'Cliente') + '*\n\nLocal Radar, benchmark dos concorrentes, estratégia e plano 30/60/90 dias reunidos em um único PDF.\n\nLEME Marketing Médico';

return [{ json: { html, nomeArquivoPdf, caption, client_name: client.nome || 'Cliente' } }];

const valor = $('Webhook Local Radar mensal').item.json.body.month_label;
const meses = { Janeiro: '01', Fevereiro: '02', Março: '03', Abril: '04', Maio: '05', Junho: '06', Julho: '07', Agosto: '08', Setembro: '09', Outubro: '10', Novembro: '11', Dezembro: '12' };
const [mes, ano] = String(valor || '').trim().split(/\s+/);
const nomePasta = `${meses[mes] || mes}/${ano || ''}`;

const itens = $input.all();
const existente = itens.find(i => String(i.json?.name || '').trim() === nomePasta);

return [{ json: { id: existente?.json?.id || '', name: existente?.json?.name || '', nome_pasta: nomePasta, pasta_existe: Boolean(existente?.json?.id) } }];

const folderId = String($input.first().json.id || '').trim();
if (!folderId) throw new Error('Não foi possível determinar a pasta mensal no Google Drive.');

const body = $('Webhook Local Radar mensal').first().json.body || {};
const pdfWebhook = String(body.pdf_base64 || '').replace(/^data:application\/pdf;base64,/i, '').trim();
const pdfAuditoria = String($('Extrair PDF final').first().json.data || '').replace(/^data:application\/pdf;base64,/i, '').trim();

if (!pdfWebhook) throw new Error('PDF do webhook não encontrado para upload no Google Drive.');
if (!pdfAuditoria) throw new Error('PDF da auditoria gerada pelo Gotenberg não encontrado para upload no Google Drive.');

const nomeWebhook = String(body.title || body.file_name || `local-radar-${body.client_name || 'cliente'}`).replace(/\.pdf$/i, '') + '.pdf';
const nomeAuditoria = String($('Montar HTML da auditoria').first().json.nomeArquivoPdf || `auditoria-gbp-${body.client_name || 'cliente'}.pdf`);

return [
  {
    json: { folder_id: folderId, file_name: nomeWebhook, origem: 'webhook' },
    binary: { data: { data: pdfWebhook, mimeType: 'application/pdf', fileName: nomeWebhook } }
  },
  {
    json: { folder_id: folderId, file_name: nomeAuditoria, origem: 'auditoria_ia' },
    binary: { data: { data: pdfAuditoria, mimeType: 'application/pdf', fileName: nomeAuditoria } }
  }
];

const folderId = String($input.first().json.id || '').trim();
if (!folderId) throw new Error('Não foi possível determinar a pasta mensal no Google Drive.');

const body = $('Validar e preparar auditoria').first().json || {};
const pdfMapa = String(body.pdf_base64 || '').replace(/^data:application\/pdf;base64,/i, '').trim();
if (!pdfMapa) throw new Error('PDF do Local Radar não encontrado para upload no Google Drive.');

const nomeMapa = String(body.file_name || body.title || `local-radar-${body.client_name || 'cliente'}`).replace(/\.pdf$/i, '') + '.pdf';
return [{
  json: { folder_id: folderId, file_name: nomeMapa, origem: 'local_radar_manual' },
  binary: { data: { data: pdfMapa, mimeType: 'application/pdf', fileName: nomeMapa } }
}];
